import React, { useEffect, useRef, useState } from "react";
import "./Ge.css";

function Generate() {
  const canvasRef = useRef();
  const containerRef = useRef();
  const [isFading, setIsFading] = useState(false);
  const [effects, setEffects] = useState({
    grain: 50,
    scanlines: 50,
    saturation: 50,
    pixelation: 50,
  });
  const [timestamp, setTimestamp] = useState(new Date());

  useEffect(() => {
    const generatedImage = localStorage.getItem("generatedImage");
    if (!generatedImage) return;

    const canvas = canvasRef.current;
    const ctx = canvas.getContext("2d");
    const img = new Image();

    img.onload = () => {
      ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
      applyEffects(ctx, canvas.width, canvas.height);
    };

    img.src = generatedImage;
    setTimestamp(new Date());

    return () => {
      // Cleanup
      localStorage.removeItem("generatedImage");
    };
  }, []);

  const applyEffects = (ctx, width, height) => {
    if (effects.grain) generateGrain(ctx, width, height);
    if (effects.scanlines) applyScanlines(ctx, width, height);
    if (effects.saturation) applySaturation(ctx, width, height);
    if (effects.pixelation) applyPixelation(ctx, width, height);
  };

  const generateGrain = (ctx, width, height, intensity = 300, gamma = 1.4) => {
    const grainData = ctx.getImageData(0, 0, width, height);
    const data = grainData.data;
    const intensityMultiplier = effects.grain / 50;
    for (let i = 0; i < data.length; i += 4) {
      const noise = Math.floor(Math.random() * intensity * intensityMultiplier) - (intensity * intensityMultiplier) / 2;
      data[i] = 255 * Math.pow(Math.min(255, Math.max(0, data[i] + noise)) / 255, 1 / gamma);
      data[i + 1] = 255 * Math.pow(Math.min(255, Math.max(0, data[i + 1] + noise)) / 255, 1 / gamma);
      data[i + 2] = 255 * Math.pow(Math.min(255, Math.max(0, data[i + 2] + noise)) / 255, 1 / gamma);
    }
    ctx.putImageData(grainData, 0, 0);
  };

  const applyScanlines = (ctx, width, height, gap = 3, alpha = 0.15) => {
    ctx.save();
    const alphaMultiplier = effects.scanlines / 50;
    ctx.fillStyle = `rgba(0,0,0,${alpha * alphaMultiplier})`;
    for (let y = 0; y < height; y += gap) {
      ctx.fillRect(0, y, width, 1);
    }
    ctx.restore();
  };

  const applySaturation = (ctx, width, height) => {
    const imageData = ctx.getImageData(0, 0, width, height);
    const data = imageData.data;
    const saturationMultiplier = effects.saturation / 50;

    for (let i = 0; i < data.length; i += 4) {
      const r = data[i];
      const g = data[i + 1];
      const b = data[i + 2];
      const gray = 0.2989 * r + 0.5870 * g + 0.1140 * b;

      data[i] = gray + (r - gray) * saturationMultiplier;
      data[i + 1] = gray + (g - gray) * saturationMultiplier;
      data[i + 2] = gray + (b - gray) * saturationMultiplier;
    }
    ctx.putImageData(imageData, 0, 0);
  };

  const applyPixelation = (ctx, width, height) => {
    const pixelSize = Math.max(1, Math.floor(20 * (1 - effects.pixelation / 100)));
    const imageData = ctx.getImageData(0, 0, width, height);
    const tempCanvas = document.createElement('canvas');
    tempCanvas.width = width;
    tempCanvas.height = height;
    const tempCtx = tempCanvas.getContext('2d');
    tempCtx.putImageData(imageData, 0, 0);

    ctx.imageSmoothingEnabled = false;
    ctx.drawImage(
      tempCanvas,
      0, 0, width, height,
      0, 0, width / pixelSize, height / pixelSize
    );
    ctx.drawImage(
      canvasRef.current,
      0, 0, width / pixelSize, height / pixelSize,
      0, 0, width, height
    );
    ctx.imageSmoothingEnabled = true;
  };

  const handleEffectChange = (effect, value) => {
    setEffects(prev => ({ ...prev, [effect]: value }));
    const canvas = canvasRef.current;
    const ctx = canvas.getContext("2d");
    const img = new Image();

    img.onload = () => {
      ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
      applyEffects(ctx, canvas.width, canvas.height);
    };

    img.src = localStorage.getItem("generatedImage");
  };

  const handleDownload = () => {
    const canvas = canvasRef.current;
    const link = document.createElement("a");
    link.download = "generated.png";
    link.href = canvas.toDataURL("image/png");
    link.click();
  };

  const handleRegenerate = () => {
    setIsFading(true);
    setTimeout(() => {
      const canvas = canvasRef.current;
      const ctx = canvas.getContext("2d");
      const img = new Image();

      img.onload = () => {
        ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
        applyEffects(ctx, canvas.width, canvas.height);
        setIsFading(false);
      };

      img.src = localStorage.getItem("generatedImage");
    }, 300);
  };

  return (
    <div ref={containerRef} className="ge-container">
      <div className="ge-control-panel">
        <div className="ge-control-group">
          <label className="ge-control-label">Grain: {effects.grain}</label>
          <input
            type="range"
            min="0"
            max="100"
            value={effects.grain}
            onChange={(e) => handleEffectChange('grain', parseInt(e.target.value))}
            className="ge-control-slider"
          />
        </div>
        <div className="ge-control-group">
          <label className="ge-control-label">Scanlines: {effects.scanlines}</label>
          <input
            type="range"
            min="0"
            max="100"
            value={effects.scanlines}
            onChange={(e) => handleEffectChange('scanlines', parseInt(e.target.value))}
            className="ge-control-slider"
          />
        </div>
        <div className="ge-control-group">
          <label className="ge-control-label">Saturation: {effects.saturation}</label>
          <input
            type="range"
            min="0"
            max="100"
            value={effects.saturation}
            onChange={(e) => handleEffectChange('saturation', parseInt(e.target.value))}
            className="ge-control-slider"
          />
        </div>
        <div className="ge-control-group">
          <label className="ge-control-label">Pixelation: {effects.pixelation}</label>
          <input
            type="range"
            min="0"
            max="100"
            value={effects.pixelation}
            onChange={(e) => handleEffectChange('pixelation', parseInt(e.target.value))}
            className="ge-control-slider"
          />
        </div>
      </div>

      <canvas
        ref={canvasRef}
        width={1080}
        height={1080}
        className="ge-canvas"
        style={{ opacity: isFading ? 0.2 : 1 }}
      />

      <div className="ge-timestamp">
        {timestamp.toLocaleString()}
      </div>

      <div className="ge-button-container">
        <button
          onClick={handleRegenerate}
          className="ge-button ge-button-regenerate"
        >
          Regenerate
        </button>
        <button
          onClick={handleDownload}
          className="ge-button ge-button-download"
        >
          Download
        </button>
      </div>
    </div>
  );
}

export default Generate;
